import datetime

start = datetime.date(2026, 10, 5)
holidays = {datetime.date(2026, 10, 12)}
phases = [("Discovery", 3), ("Build", 6), ("QA", 4), ("Release", 1)]

def is_business_day(d):
    return d.weekday() < 5 and d not in holidays

def add_business_days(start_day, n):
    # start_day counts as day 1 if it's a business day; walk n business days total inclusive
    d = start_day
    count = 0
    last = None
    while count < n:
        if is_business_day(d):
            count += 1
            last = d
        if count < n:
            d += datetime.timedelta(days=1)
    return last

def next_business_day(d):
    d += datetime.timedelta(days=1)
    while not is_business_day(d):
        d += datetime.timedelta(days=1)
    return d

cursor = start
for name, dur in phases:
    end = add_business_days(cursor, dur)
    print(f"{name}: {cursor} -> {end} ({dur} business days)")
    cursor = next_business_day(end)

print("Launch date:", end, end.strftime("%A"))
EOF
